/*
 * node_modules/express — Express-shaped router for the SEVM stack.
 *
 * Full compatibility layer on top of the node:http surface in
 * node_modules/net: middleware chain (app.use), path parameters
 * (/items/:id), query strings, body parsing (express.json/urlencoded/text),
 * static file serving (express.static) and the usual res helpers
 * (set/type/attachment/redirect/status/json/send/end).
 */

import { createServer } from '../net/index.js';
import * as fs from '../mochifs/index.js';

const MIME = {
    '.html': 'text/html; charset=utf-8', '.htm': 'text/html; charset=utf-8',
    '.js': 'application/javascript', '.mjs': 'application/javascript',
    '.css': 'text/css', '.json': 'application/json',
    '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
    '.gif': 'image/gif', '.svg': 'image/svg+xml', '.ico': 'image/x-icon',
    '.txt': 'text/plain; charset=utf-8', '.map': 'application/json',
    '.woff': 'font/woff', '.woff2': 'font/woff2', '.ttf': 'font/ttf',
    '.webp': 'image/webp', '.avif': 'image/avif',
};

function extname(p) {
    const i = p.lastIndexOf('.');
    return i < 0 ? '' : p.slice(i).toLowerCase();
}

function mimeFor(path) {
    return MIME[extname(path)] || 'application/octet-stream';
}

/* /items/:id -> ^/items/([^/]+)$ with keys ['id']; '*' -> .* */
function compilePath(pattern) {
    const keys = [];
    const re = pattern
        .replace(/[.*+?^${}()|[\]\\]/g, (m) => (m === '*' ? '\u0000' : '\\' + m))
        .replace(/\u0000/g, '.*')
        .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (m, k) => {
            keys.push(k);
            return '([^/]+)';
        });
    return { re: new RegExp('^' + re + '$'), keys };
}

function matchPath(pattern, path) {
    const { re, keys } = compilePath(pattern);
    const m = re.exec(path);
    if (!m) return null;
    const params = Object.create(null);
    for (let i = 0; i < keys.length; i++) params[keys[i]] = decodeURIComponent(m[i + 1]);
    return params;
}

/* parse the raw body string by content-type; idempotent per request */
function parseBody(req) {
    if (req._parsedBody !== undefined) return req._parsedBody;
    const ct = (req.headers['content-type'] || '').toLowerCase();
    let out;
    if (req.body && req.body.length) {
        if (ct.includes('application/json')) {
            try { out = JSON.parse(req.body); } catch (e) { out = {}; }
        } else if (ct.includes('application/x-www-form-urlencoded')) {
            out = Object.create(null);
            for (const pair of req.body.split('&')) {
                if (!pair) continue;
                const eq = pair.indexOf('=');
                const k = eq >= 0 ? pair.slice(0, eq) : pair;
                const v = eq >= 0 ? pair.slice(eq + 1) : '';
                out[decodeURIComponent(k.replace(/\+/g, ' '))] =
                    decodeURIComponent(v.replace(/\+/g, ' '));
            }
        } else out = req.body;
    } else out = {};
    req._parsedBody = out;
    return out;
}

export function express() {
    /* stack entries: {method|null, path|null, fn} — method null => middleware */
    const stack = [];

    function layerMatched(l, req) {
        if (l.method) {
            if (l.method !== req.method) return false;
            if (l.path && !matchPath(l.path, req.path)) return false;
            return true;
        }
        /* middleware: path is a prefix match */
        if (l.path) {
            if (req.path !== l.path && !req.path.startsWith(l.path + '/')) return false;
        }
        return true;
    }

    function dispatch(req, res, i) {
        if (i >= stack.length) {
            res.status(404).json({ error: 'Not Found', path: req.path });
            return;
        }
        const l = stack[i];
        if (!layerMatched(l, req)) { dispatch(req, res, i + 1); return; }

        const routeParams = l.method ? matchPath(l.path, req.path) : null;
        if (routeParams) Object.assign(req.params, routeParams);

        const next = (err) => {
            if (err) {
                res.status(500).json({ error: String(err && err.message ? err.message : err) });
                return;
            }
            dispatch(req, res, i + 1);
        };
        try {
            l.fn(req, res, next);
        } catch (e) {
            res.status(500).json({ error: String(e && e.message ? e.message : e) });
        }
    }

    function app(req, res) {
        if (!req.params) req.params = Object.create(null);
        if (!req.query) req.query = Object.create(null);
        if (!req.body) req.body = '';
        if (!req.get) req.get = (k) => req.headers[String(k).toLowerCase()];
        dispatch(req, res, 0);
    }

    for (const m of ['get', 'post', 'put', 'delete', 'patch', 'head', 'options']) {
        app[m] = (path, ...fns) => {
            for (const fn of fns) stack.push({ method: m.toUpperCase(), path, fn });
            return app;
        };
    }

    app.use = (arg, ...fns) => {
        let path = null;
        if (typeof arg === 'string') path = arg;
        else fns = [arg, ...fns];
        for (const fn of fns) {
            /* hand the mount path to middlewares that expose a __mount slot
               (express.static strips it before resolving the file) */
            if (path && typeof fn === 'function' && '__mount' in fn) fn.__mount = path;
            stack.push({ method: null, path, fn });
        }
        return app;
    };

    app.listen = (port, onListen) => {
        const server = createServer(app);
        return server.listen(port, onListen);
    };

    return app;
}

/* ---- body parsers (middleware) ---- */
express.json = () => (req, res, next) => { req.body = parseBody(req); next(); };
express.urlencoded = () => (req, res, next) => { req.body = parseBody(req); next(); };
express.text = () => (req, res, next) => { req.body = String(req.body || ''); next(); };

/* ---- static file serving ---- */
express.static = (root, opts = {}) => {
    const mw = (req, res, next) => {
        if (req.method !== 'GET' && req.method !== 'HEAD') return next();
        let rel = req.path;
        if (mw.__mount && rel.startsWith(mw.__mount)) rel = rel.slice(mw.__mount.length);
        else if (opts.prefix && rel.startsWith(opts.prefix)) rel = rel.slice(opts.prefix.length);
        if (rel === '/') rel = '/index.html';
        if (rel.includes('..')) return next();          /* traversal guard */
        const full = root.replace(/\/$/, '') + rel;
        try {
            if (!fs.existsSync(full)) return next();
            const st = fs.statSync(full);
            if (st.isDirectory && st.isDirectory()) return next();
            const data = fs.readFileSync(full);
            res.type(mimeFor(full)).end(String(data));
        } catch (e) { next(e); }
    };
    mw.__mount = null;
    return mw;
};

export default express;

